(33409, 'Joshua 21:43', 'Joshua', 21, 43, 'نو څښتن اسراییلو ته هغه ټوله ځمکه ورکړه چې د هغوی د نیکونو سره یې قسم خوړلی ؤ. هغوی د دې ځمکې ملکیت تر لاسه کړ او هلته ځای په ځای شول.', 'نو چشتن اسراییلو ته هغه توله جمکه ورکره چې د هغوی د نیکونو سره یې قسم خورلی و. هغوی د دې جمکې ملکیت تر لاسه کر او هلته جای په جای شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_21_43.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33410, 'Joshua 21:44', 'Joshua', 21, 44, 'لکه څنګه چې څښتن د هغوی د نیکونو سره وعده کړې وه، هغه د هغوی په ټوله خاوره کې ارامي راوستله. د هغوی یو دښمن هم نه شو کولای چې د هغوی په وړاندې ودریږي، ځکه چې څښتن اسراییلیانو ته په خپلو ټولو دښمنانو باندې بری ورکړی ؤ.', 'لکه چنګه چې چشتن د هغوی د نیکونو سره وعده کرې وه، هغه د هغوی په توله خاوره کې ارامی راوستله. د هغوی یو دشمن هم نه شو کولای چې د هغوی په وراندې ودریزی، جکه چې چشتن اسراییلیانو ته په خپلو تولو دشمنانو باندې بری ورکری و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_21_44.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33411, 'Joshua 21:45', 'Joshua', 21, 45, 'څښتن چې کومې وعدې د اسراییلو د قوم سره کړې وې، هغه ټولې یې سرته ورسولې.', 'چشتن چې کومې وعدې د اسراییلو د قوم سره کرې وې، هغه تولې یې سرته ورسولې.', 'OT', 'afghan2023', 'afghan', '', '', 1761237837, 1761237837),
(33412, 'Jeremiah 17:1', 'Jeremiah', 17, 1, 'مالِک خُدائ فرمائى چې، ”د يهوداه د خلقو ګناه د اوسپنې په قلم چې نوکه يې د هيرې ده، ستاسو د کاڼو نه په سختو زړُونو نقش شوې ده او ستاسو د قربان‌ګاه په ګوټونو ليکلې شوې ده.', 'مالک خدای فرمایی چې، ”د یهوداه د خلقو ګناه د اوسپنې په قلم چې نوکه یې د هیرې ده، ستاسو د کانو نه په سختو زرونو نقش شوې ده او ستاسو د قربان‌ګاه په ګوتونو لیکلې شوې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33413, 'Jeremiah 17:2', 'Jeremiah', 17, 2, 'نۀ صرف تاسو بلکې ستاسو بچى هم خپلې قربان‌ګاه او د اشيرې بُت شکلونه همېشه رايادوى کۀ د شنې ونې په خوا کښې وى او کۀ په اوچته غونډۍ وى.', 'نۀ صرف تاسو بلکې ستاسو بچی هم خپلې قربان‌ګاه او د اشیرې بت شکلونه همېشه رایادوی کۀ د شنې ونې په خوا کشې وی او کۀ په اوچته غوندی وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33414, 'Jeremiah 17:3', 'Jeremiah', 17, 3, 'نو زۀ به په دې مُلک کښې خپل مقدس غر سره ستاسو د ټول مال دولت او ستاسو علاقائى عبادتخانې نورو خلقو ته د غنيمت په توګه حواله کړم، دا ستاسو د ګناهونو بدل دے کوم چې تاسو په خپل ټول مُلک کښې کړې دى.', 'نو زۀ به په دې ملک کشې خپل مقدس غر سره ستاسو د تول مال دولت او ستاسو علاقایی عبادتخانې نورو خلقو ته د غنیمت په توګه حواله کرم، دا ستاسو د ګناهونو بدل دے کوم چې تاسو په خپل تول ملک کشې کرې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33415, 'Jeremiah 17:4', 'Jeremiah', 17, 4, 'ستاسو د خپلې ګناه په وجه به هغه مُلک ستاسو د لاس نه ووځى کوم چې ما تاسو ته په ميراث کښې درکړے دے. زۀ به تاسو په هغه مُلکونو کښې چې تاسو يې نۀ پېژنئ دشمنانو ته د غلام په شکل حواله کړم. ځکه چې تاسو زما د غصې اور بل کړے دے او هغه به تل بليږى.“', 'ستاسو د خپلې ګناه په وجه به هغه ملک ستاسو د لاس نه ووجی کوم چې ما تاسو ته په میراث کشې درکرے دے. زۀ به تاسو په هغه ملکونو کشې چې تاسو یې نۀ پېژنی دشمنانو ته د غلام په شکل حواله کرم. جکه چې تاسو زما د غصې اور بل کرے دے او هغه به تل بلیزی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33416, 'Jeremiah 17:5', 'Jeremiah', 17, 5, 'مالِک خُدائ فرمائى چې، ”لعنت دې په هغه چا وى چې د هغۀ زړۀ د مالِک خُدائ نه اوړېدلے وى او په فانى انسان توکل او د هغۀ په زور بهروسه کوى.', 'مالک خدای فرمایی چې، ”لعنت دې په هغه چا وی چې د هغۀ زرۀ د مالک خدای نه اورېدلے وی او په فانی انسان توکل او د هغۀ په زور بهروسه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33417, 'Jeremiah 17:6', 'Jeremiah', 17, 6, 'هغه د بيابان د هغه بوټى په شان دے، کۀ څۀ هم چې خير وى خو هغوئ ته به مِلاو نۀ شى. ځکه چې هغه به د بيابان په خشکه او مالګينه زمکه کښې شوے وى، چرته چې نور څۀ نۀ کيږى.', 'هغه د بیابان د هغه بوتی په شان دے، کۀ چۀ هم چې خیر وی خو هغوی ته به ملاو نۀ شی. جکه چې هغه به د بیابان په خشکه او مالګینه زمکه کشې شوے وی، چرته چې نور چۀ نۀ کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33418, 'Jeremiah 17:7', 'Jeremiah', 17, 7, 'خو بختور دى هغوئ څوک چې په مالِک خُدائ يقين لرى، او په مالِک خُدائ يې توکل کړے وى.', 'خو بختور دی هغوی چوک چې په مالک خدای یقین لری، او په مالک خدای یې توکل کرے وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33419, 'Jeremiah 17:8', 'Jeremiah', 17, 8, 'هغوئ د هغه ونو په شان دى چې د لختى په غاړه کَرلے شوې وى او جرړې يې اوبو ته رسېدلې وى. نو کله چې د ګرمۍ موسم راشى نو يره يې نۀ وى، د هغوئ پاڼې هر وخت شنې وى. او په خُشک سالۍ کښې يې څۀ پرېشانى نۀ وى، نو کله هم بې‌مېوې نۀ پاتې کيږى.“', 'هغوی د هغه ونو په شان دی چې د لختی په غاره کرلے شوې وی او جررې یې اوبو ته رسېدلې وی. نو کله چې د ګرمی موسم راشی نو یره یې نۀ وی، د هغوی پانې هر وخت شنې وی. او په خشک سالی کشې یې چۀ پرېشانی نۀ وی، نو کله هم بې‌مېوې نۀ پاتې کیزی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33420, 'Jeremiah 17:9', 'Jeremiah', 17, 9, 'د انسان زړۀ د هر څۀ نه زيات دوکه مار وى، او د شرارت نه ډک وى. څوک پرې هم نۀ پوهيږى.', 'د انسان زرۀ د هر چۀ نه زیات دوکه مار وی، او د شرارت نه دک وی. چوک پرې هم نۀ پوهیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33421, 'Jeremiah 17:10', 'Jeremiah', 17, 10, '”زۀ مالِک خُدائ د انسان د زړۀ لټون کوم او د هغۀ پټ سوچونه آزمائيم، زۀ هر چا ته اجر د هغۀ د عمل په مطابق ورکوم.“', '”زۀ مالک خدای د انسان د زرۀ لتون کوم او د هغۀ پت سوچونه ازماییم، زۀ هر چا ته اجر د هغۀ د عمل په مطابق ورکوم.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33422, 'Jeremiah 17:11', 'Jeremiah', 17, 11, 'هغه څوک چې په ناجائزه طريقې سره مال دولت راجمع کړى هغه د هغه تيتر په شان وى چې پردۍ هګۍ وشاربى کومې چې هغې اچولې نۀ وى، نو وروستو به د هغۀ نه ټول مال دولت لاړ شى، کله چې د هغۀ عمر نيم تېر شى نو د هغۀ مال دولت به د هغۀ نه والوځى او په آخر کښې به دے خپل ځان کم عقل ثابت کړى.', 'هغه چوک چې په ناجایزه طریقې سره مال دولت راجمع کری هغه د هغه تیتر په شان وی چې پردی هګی وشاربی کومې چې هغې اچولې نۀ وی، نو وروستو به د هغۀ نه تول مال دولت لار شی، کله چې د هغۀ عمر نیم تېر شی نو د هغۀ مال دولت به د هغۀ نه والوجی او په اخر کشې به دے خپل جان کم عقل ثابت کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33423, 'Jeremiah 17:12', 'Jeremiah', 17, 12, 'خو هغه جلالى تخت چې د ازل نه اوچت دے، هغه زمونږ د خُدائ پاک مقدس کور دے.', 'خو هغه جلالی تخت چې د ازل نه اوچت دے، هغه زمونز د خدای پاک مقدس کور دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33424, 'Jeremiah 17:13', 'Jeremiah', 17, 13, 'اے مالِکه خُدايه، د بنى اِسرائيلو اُميده، هر څوک چې تا نه مخ واړوى هغوئ ټول به ټيټ سترګې او شرمنده شى. هغوئ چا چې تا نه مخ اړولے دے په دوړو د ليکلو په شان دى، دوئ به زر ختم شى ځکه چې هغوئ د هغه مالِک خُدائ نه مخ اړولے دے څوک چې د ژوندون د اوبو چينه ده.', 'اے مالکه خدایه، د بنی اسراییلو امیده، هر چوک چې تا نه مخ واروی هغوی تول به تیت سترګې او شرمنده شی. هغوی چا چې تا نه مخ ارولے دے په دورو د لیکلو په شان دی، دوی به زر ختم شی جکه چې هغوی د هغه مالک خدای نه مخ ارولے دے چوک چې د ژوندون د اوبو چینه ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33425, 'Jeremiah 17:14', 'Jeremiah', 17, 14, 'اے مالِکه خُدايه، کۀ چرې تۀ ما له شفا راکړې نو زۀ به بلکل روغ رمټ شم، کۀ چرې تۀ ما له خلاصون راکړې نو زۀ به بچ شم، ځکه چې زۀ صرف ستا ثناء صِفت کوم.', 'اے مالکه خدایه، کۀ چرې تۀ ما له شفا راکرې نو زۀ به بلکل روغ رمت شم، کۀ چرې تۀ ما له خلاصون راکرې نو زۀ به بچ شم، جکه چې زۀ صرف ستا ثناء صفت کوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33426, 'Jeremiah 17:15', 'Jeremiah', 17, 15, 'هغوئ ما ته بار بار دا وائى چې، د مالِک خُدائ هغه کارونه څۀ شول د چا د پوره کېدلو په حقله چې هغۀ پېشګوئې کړې وه؟ نو اوس دې هغه پوره کړى.', 'هغوی ما ته بار بار دا وایی چې، د مالک خدای هغه کارونه چۀ شول د چا د پوره کېدلو په حقله چې هغۀ پېشګویې کرې وه؟ نو اوس دې هغه پوره کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33427, 'Jeremiah 17:16', 'Jeremiah', 17, 16, 'اے مالِکه خُدايه، زۀ د هغه کار نه نۀ يم تښتېدلے د کوم دپاره چې تاسو زۀ د خپل قوم دپاره د شپونکى په حيثيت مقرر کړے يم. تاسو ته پته ده چې ما په هغوئ د افت د ورځې د راتلو خواهش نۀ دے کړے. زما د شونډو نه چې څۀ هم وتلى دى هغه ستا په وړاندې څرګند دى.', 'اے مالکه خدایه، زۀ د هغه کار نه نۀ یم تشتېدلے د کوم دپاره چې تاسو زۀ د خپل قوم دپاره د شپونکی په حیثیت مقرر کرے یم. تاسو ته پته ده چې ما په هغوی د افت د ورجې د راتلو خواهش نۀ دے کرے. زما د شوندو نه چې چۀ هم وتلی دی هغه ستا په وراندې چرګند دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33428, 'Jeremiah 17:17', 'Jeremiah', 17, 17, 'مالِکه خُدايه، ما مۀ يروه، د افت په ورځ صرف تۀ زما اُميد يې.', 'مالکه خدایه، ما مۀ یروه، د افت په ورج صرف تۀ زما امید یې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33429, 'Jeremiah 17:18', 'Jeremiah', 17, 18, 'زما دشمنان دې وشرميږى خو ما مۀ شرموه، په هغوئ يره راوله خو ما مۀ يروه. په هغوئ د افت ورځې راوله، او هغوئ په دوه چنده تباه کړه.', 'زما دشمنان دې وشرمیزی خو ما مۀ شرموه، په هغوی یره راوله خو ما مۀ یروه. په هغوی د افت ورجې راوله، او هغوی په دوه چنده تباه کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33430, 'Jeremiah 17:19', 'Jeremiah', 17, 19, 'مالِک خُدائ ما ته وفرمائيل، ”يرمياه، لاړ شه او د عوامى دروازې په خولۀ کښې ودرېږه په کومه چې د يهوداه بادشاهان ځى راځى او هم داسې د يروشلم په نورو دروازو کښې ودرېږه.', 'مالک خدای ما ته وفرماییل، ”یرمیاه، لار شه او د عوامی دروازې په خولۀ کشې ودرېزه په کومه چې د یهوداه بادشاهان جی راجی او هم داسې د یروشلم په نورو دروازو کشې ودرېزه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33431, 'Jeremiah 17:20', 'Jeremiah', 17, 20, 'هغوئ ته ووايه، د مالِک خُدائ پېغام واورئ. اے د يهوداه بادشاهانو او د يهوداه ټولو خلقو او د يروشلم اوسېدونکو او هغوئ ټولو ته چې په دې دروازې ځى راځى.', 'هغوی ته ووایه، د مالک خدای پېغام واوری. اے د یهوداه بادشاهانو او د یهوداه تولو خلقو او د یروشلم اوسېدونکو او هغوی تولو ته چې په دې دروازې جی راجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33432, 'Jeremiah 17:21', 'Jeremiah', 17, 21, 'مالِک خُدائ فرمائى چې، خبردار چې د سبت په ورځ په خپل سر پنډ مۀ اوچتوئ او د يروشلم په دروازو پنډ سره مۀ ننوځئ.', 'مالک خدای فرمایی چې، خبردار چې د سبت په ورج په خپل سر پند مۀ اوچتوی او د یروشلم په دروازو پند سره مۀ ننوجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33433, 'Jeremiah 17:22', 'Jeremiah', 17, 22, 'او تر دې چې په خپلو کورونو کښې هم د سبت په ورځ هيڅ قسمه کار مۀ کوئ او مۀ څۀ بار اوچتوئ. خو د سبت ورځ مقدسه وساتئ لکه څنګه چې ما ستاسو پلار نيکۀ ته حکم کړے وو.', 'او تر دې چې په خپلو کورونو کشې هم د سبت په ورج هیچ قسمه کار مۀ کوی او مۀ چۀ بار اوچتوی. خو د سبت ورج مقدسه وساتی لکه چنګه چې ما ستاسو پلار نیکۀ ته حکم کرے وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33434, 'Jeremiah 17:23', 'Jeremiah', 17, 23, 'خو هغوئ ما ته غوږ ونۀ نيولو او نۀ يې ما ته توجو راکړه او نۀ يې زما پيروى وکړه. خو هغوئ سرکشه وُو او اصلاح کولو ته يې جواب ورنۀ کړو.', 'خو هغوی ما ته غوز ونۀ نیولو او نۀ یې ما ته توجو راکره او نۀ یې زما پیروی وکره. خو هغوی سرکشه وو او اصلاح کولو ته یې جواب ورنۀ کرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33435, 'Jeremiah 17:24', 'Jeremiah', 17, 24, 'خو مالِک خُدائ فرمائى، کۀ چرې تاسو زما خبره ومنئ او د سبت په ورځ په دې دروازو د تجارت دپاره څۀ داخل نۀ کړئ او نۀ څۀ کار وکړئ، او هغه مقدسه وساتئ،', 'خو مالک خدای فرمایی، کۀ چرې تاسو زما خبره ومنی او د سبت په ورج په دې دروازو د تجارت دپاره چۀ داخل نۀ کری او نۀ چۀ کار وکری، او هغه مقدسه وساتی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33436, 'Jeremiah 17:25', 'Jeremiah', 17, 25, 'نو بيا به هغه بادشاهان څوک چې د داؤد په تخت ناست دى نو هغوئ به د خپلو آفسرانو سره د دې ښار په دروازو ځى راځى. او هغوئ او د هغوئ آفسران به په آسونو او ګاډو سوارۀ راشى، او د يهوداه خلق به ورسره وى او هغوئ څوک چې په يروشلم کښې اوسيږى، او دا ښار به د تل دپاره آباد وى.', 'نو بیا به هغه بادشاهان چوک چې د داود په تخت ناست دی نو هغوی به د خپلو افسرانو سره د دې شار په دروازو جی راجی. او هغوی او د هغوی افسران به په اسونو او ګادو سوارۀ راشی، او د یهوداه خلق به ورسره وی او هغوی چوک چې په یروشلم کشې اوسیزی، او دا شار به د تل دپاره اباد وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33437, 'Jeremiah 17:26', 'Jeremiah', 17, 26, 'د يهوداه د ښارونو او د يروشلم د ګېرچاپېره کلو نه به خلق راشى، هغوئ به د بنيامين د علاقې، د مغربى غونډو د لمنو نه، او د نجب او د غريزې علاقې نه به د خپلو سوزېدونکو نذرانو او قربانو سره راشى. هغوئ به د خپلو غلو دانو او خوشبوئى د شکرانې نذرانې سره د مالِک خُدائ کور ته راشى.', 'د یهوداه د شارونو او د یروشلم د ګېرچاپېره کلو نه به خلق راشی، هغوی به د بنیامین د علاقې، د مغربی غوندو د لمنو نه، او د نجب او د غریزې علاقې نه به د خپلو سوزېدونکو نذرانو او قربانو سره راشی. هغوی به د خپلو غلو دانو او خوشبویی د شکرانې نذرانې سره د مالک خدای کور ته راشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33438, 'Jeremiah 17:27', 'Jeremiah', 17, 27, 'خو کۀ تاسو زما خبره ونۀ منئ او د سبت ورځ مقدسه ونۀ ساتئ، او لکه د نورو ورځو په شان د سبت په ورځ د سودا پنډونه د يروشلم دروازو ته راؤړئ، نو بيا به زۀ په دې دروازو اور بل کړم. او دا اور به د يروشلم محلونه وسوزوى. او د دې اور لمبې به هيڅوک مړې کولے نۀ شى.“', 'خو کۀ تاسو زما خبره ونۀ منی او د سبت ورج مقدسه ونۀ ساتی، او لکه د نورو ورجو په شان د سبت په ورج د سودا پندونه د یروشلم دروازو ته راوری، نو بیا به زۀ په دې دروازو اور بل کرم. او دا اور به د یروشلم محلونه وسوزوی. او د دې اور لمبې به هیچوک مرې کولے نۀ شی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_17_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33439, 'Jeremiah 20:1', 'Jeremiah', 20, 1, 'کله چې فشحور د اِمير زوئ څوک چې د مالِک خُدائ په کور کښې مشر اِمام وو، هغه څۀ واورېدل د څۀ چې يرمياه پېشګوئې کوله،', 'کله چې فشحور د امیر زوی چوک چې د مالک خدای په کور کشې مشر امام وو، هغه چۀ واورېدل د چۀ چې یرمیاه پېشګویې کوله،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33440, 'Jeremiah 20:2', 'Jeremiah', 20, 2, 'نو هغۀ يرمياه نبى راګېر کړلو او په کوړو يې ووهلو او بيا يې هغه پاس د مالِک خُدائ په کور کښې د بنيامين په دروازه کښې د لرګى په کُنده کښې بند کړلو.', 'نو هغۀ یرمیاه نبی راګېر کرلو او په کورو یې ووهلو او بیا یې هغه پاس د مالک خدای په کور کشې د بنیامین په دروازه کشې د لرګی په کنده کشې بند کرلو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33441, 'Jeremiah 20:3', 'Jeremiah', 20, 3, 'په بله ورځ کله چې فشحور هغه د کُندې نه آزاد کړو، يرمياه هغۀ ته وفرمائيل چې، ”مالِک خُدائ ستا نوے نوم اېښے دے او د نن نه پس به ستا نوم فشحور نۀ وى بلکې په هر اړخ باندې دهشت.', 'په بله ورج کله چې فشحور هغه د کندې نه ازاد کرو، یرمیاه هغۀ ته وفرماییل چې، ”مالک خدای ستا نوے نوم اېشے دے او د نن نه پس به ستا نوم فشحور نۀ وی بلکې په هر ارخ باندې دهشت.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33442, 'Jeremiah 20:4', 'Jeremiah', 20, 4, 'ځکه مالِک خُدائ په خپله دا فرمائى چې، زۀ به په تا او ستا په دوستانو باندې دهشت راولم، او تۀ به په خپلو سترګو سره د هغوئ وژل د دشمنانو د لاسه ووينې. زۀ به د يهوداه ټول خلق د بابل بادشاه ته حواله کړم، څوک چې به د هغوئ نه ځينې بابل ته قېديان بوځى او ځينې به په تُوره قتل کړى.', 'جکه مالک خدای په خپله دا فرمایی چې، زۀ به په تا او ستا په دوستانو باندې دهشت راولم، او تۀ به په خپلو سترګو سره د هغوی وژل د دشمنانو د لاسه ووینې. زۀ به د یهوداه تول خلق د بابل بادشاه ته حواله کرم، چوک چې به د هغوی نه جینې بابل ته قېدیان بوجی او جینې به په توره قتل کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33443, 'Jeremiah 20:5', 'Jeremiah', 20, 5, 'زۀ به د دې ښار ټول مال دولت او د هغوئ ټول قيمتى سامانونه او د يهوداه بادشاه خزانې د هغوئ دشمنانو ته حواله کړم. هغوئ به دا لوټ کړى او بابل ته به يې يوسى.', 'زۀ به د دې شار تول مال دولت او د هغوی تول قیمتی سامانونه او د یهوداه بادشاه خزانې د هغوی دشمنانو ته حواله کرم. هغوی به دا لوت کری او بابل ته به یې یوسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33444, 'Jeremiah 20:6', 'Jeremiah', 20, 6, 'ترڅو چې ستا خبره ده فشحوره، تۀ او ستا مکمل خاندان به هم ونيولے شى او بابل ته به بوتلے شى. هلته به تاسو او ستا هغه ټول دوستان مړۀ او ښخ شى چا ته به چې تا په دروغو پېشګوئې کوله چې هيڅ پرواه مۀ کوئ خير به شى.“', 'ترچو چې ستا خبره ده فشحوره، تۀ او ستا مکمل خاندان به هم ونیولے شی او بابل ته به بوتلے شی. هلته به تاسو او ستا هغه تول دوستان مرۀ او شخ شی چا ته به چې تا په دروغو پېشګویې کوله چې هیچ پرواه مۀ کوی خیر به شی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33445, 'Jeremiah 20:7', 'Jeremiah', 20, 7, 'اے مالِکه خُدايه، تا زۀ دوکه کړم، او زۀ دوکه شوم. تاسو زورَور يئ او زۀ دې مغلوب کړم. زۀ اوس ټوله ورځ د مسخرو شوم، او هر څوک ما پورې ټوقې او خندا کوى.', 'اے مالکه خدایه، تا زۀ دوکه کرم، او زۀ دوکه شوم. تاسو زورور یی او زۀ دې مغلوب کرم. زۀ اوس توله ورج د مسخرو شوم، او هر چوک ما پورې توقې او خندا کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33446, 'Jeremiah 20:8', 'Jeremiah', 20, 8, 'کله چې هم زۀ خپله خولۀ خلاصوم، نو بيا ضرور زۀ د ظلم او تباهۍ په حقله چغې سورې وهم. ځکه چې زۀ د مالِک خُدائ د کلام په وجه ټوله ورځ کنځل او بدې ردې تېروم او سپکولے شم.', 'کله چې هم زۀ خپله خولۀ خلاصوم، نو بیا ضرور زۀ د ظلم او تباهی په حقله چغې سورې وهم. جکه چې زۀ د مالک خدای د کلام په وجه توله ورج کنجل او بدې ردې تېروم او سپکولے شم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33447, 'Jeremiah 20:9', 'Jeremiah', 20, 9, 'خو چې کله زۀ ووايم چې، ”زۀ به د مالِک خُدائ په حقله خبرې نۀ کوم او نۀ به نور د هغۀ پېغام چا ته رسوم،“ نو بيا د هغۀ کلام زما په زړۀ کښې لکه د اور په شان بليږى او هغه اور زما هډوکو ته رسيږى. زۀ په ځان کښې د هغۀ د ايسارولو د کوشش په وجه ډېر ستړے شوے يم او زۀ هغه نۀ شم ايسارولے.', 'خو چې کله زۀ ووایم چې، ”زۀ به د مالک خدای په حقله خبرې نۀ کوم او نۀ به نور د هغۀ پېغام چا ته رسوم،“ نو بیا د هغۀ کلام زما په زرۀ کشې لکه د اور په شان بلیزی او هغه اور زما هدوکو ته رسیزی. زۀ په جان کشې د هغۀ د ایسارولو د کوشش په وجه دېر سترے شوے یم او زۀ هغه نۀ شم ایسارولے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33448, 'Jeremiah 20:10', 'Jeremiah', 20, 10, 'ما د خپل ځان په حقله د ډېرو خلقو ګونګوسى اورېدلى دى. هغوئ وائى چې، ”هرې خوا ته دهشت دے بس دهشت. راځئ چې د هغۀ اِطلاع ورکړُو. راځئ چې د هغۀ په حقله اِطلاع ورکړُو.“ زما نزدې دوستان هم زما د غورزېدلو په انتظار دى، او هغوئ وائى چې، ”شايد چې هغه دوکه شى، نو بيا به يې راګېر کړُو او د هغۀ نه به خپله بدله واخلو.“', 'ما د خپل جان په حقله د دېرو خلقو ګونګوسی اورېدلی دی. هغوی وایی چې، ”هرې خوا ته دهشت دے بس دهشت. راجی چې د هغۀ اطلاع ورکرو. راجی چې د هغۀ په حقله اطلاع ورکرو.“ زما نزدې دوستان هم زما د غورزېدلو په انتظار دی، او هغوی وایی چې، ”شاید چې هغه دوکه شی، نو بیا به یې راګېر کرو او د هغۀ نه به خپله بدله واخلو.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33449, 'Jeremiah 20:11', 'Jeremiah', 20, 11, 'بلکې مالِک خُدائ د يو طاقتور جنګيالى په شان ما سره دے، نو بيا څوک هم چې زما د ژوند ختمولو پسې دى هغوئ به هيڅکله هم کامياب نۀ شى، او په خپله به تيندکونه وخورى. هغوئ به ناکاميابه شى او په شرمونو به وشرميږى، د هغوئ دا بې‌عزتى به هيڅکله د هېرېدلو نۀ وى.', 'بلکې مالک خدای د یو طاقتور جنګیالی په شان ما سره دے، نو بیا چوک هم چې زما د ژوند ختمولو پسې دی هغوی به هیچکله هم کامیاب نۀ شی، او په خپله به تیندکونه وخوری. هغوی به ناکامیابه شی او په شرمونو به وشرمیزی، د هغوی دا بې‌عزتی به هیچکله د هېرېدلو نۀ وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33450, 'Jeremiah 20:12', 'Jeremiah', 20, 12, 'خو اے مالِکه خُدايه، ربُ الافواجه، تاسو په خپله صادق سړے وينئ، او تاسو په خپله د انسان د زړۀ او دماغ ژور سوچونه او رازونه آزمايئ. ما خپل خواست تا ته پېش کړے دے نو په دې وجه تاسو زما بدله اخستل ما ته وښايئ.', 'خو اے مالکه خدایه، رب الافواجه، تاسو په خپله صادق سرے وینی، او تاسو په خپله د انسان د زرۀ او دماغ ژور سوچونه او رازونه ازمایی. ما خپل خواست تا ته پېش کرے دے نو په دې وجه تاسو زما بدله اخستل ما ته وشایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33451, 'Jeremiah 20:13', 'Jeremiah', 20, 13, 'د مالِک خُدائ حمد ووايئ. د مالِک خُدائ ثناء صِفت ادا کړئ. هغه غريبانان د شريرانو د لاس نه بچ کوى.', 'د مالک خدای حمد ووایی. د مالک خدای ثناء صفت ادا کری. هغه غریبانان د شریرانو د لاس نه بچ کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33452, 'Jeremiah 20:14', 'Jeremiah', 20, 14, 'په هغه ورځ دې لعنت وى په کومه چې زۀ پېدا شوے وم. او هغه ورځ دې مبارکه نۀ وى په کومه ورځ چې زۀ د مور نه پېدا شوم.', 'په هغه ورج دې لعنت وی په کومه چې زۀ پېدا شوے وم. او هغه ورج دې مبارکه نۀ وی په کومه ورج چې زۀ د مور نه پېدا شوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33453, 'Jeremiah 20:15', 'Jeremiah', 20, 15, 'په هغه کس دې لعنت وى چا چې زما د پلار د خوشحالولو دپاره دا زېرے راوړے وو چې، ”ستا زوئ پېدا شوے دے.“', 'په هغه کس دې لعنت وی چا چې زما د پلار د خوشحالولو دپاره دا زېرے راورے وو چې، ”ستا زوی پېدا شوے دے.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33454, 'Jeremiah 20:16', 'Jeremiah', 20, 16, 'هغه سړے دې د هغه ښارونو په شان شى کوم چې مالِک خُدائ په بې‌رحمۍ سره تباه کړى وُو. هغه دې په سحر کښې د يرې چغې واورى او په غرمه کښې دې د جنګ شور واورى،', 'هغه سرے دې د هغه شارونو په شان شی کوم چې مالک خدای په بې‌رحمی سره تباه کری وو. هغه دې په سحر کشې د یرې چغې واوری او په غرمه کشې دې د جنګ شور واوری،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33455, 'Jeremiah 20:17', 'Jeremiah', 20, 17, 'ځکه چې زۀ هغۀ د پېدا کېدو نه وړاندې د مور په ګېډه کښې مړ نۀ کړم، ترڅو چې د هغې ګېډه زما قبر جوړ شوے وے.', 'جکه چې زۀ هغۀ د پېدا کېدو نه وراندې د مور په ګېده کشې مر نۀ کرم، ترچو چې د هغې ګېده زما قبر جور شوے وے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33456, 'Jeremiah 20:18', 'Jeremiah', 20, 18, 'زۀ د مور د خېټې نه ولې دُنيا ته راغلم؟ د دې دپاره پېدا شوم چې په دُنيا کښې تکليفونه او کړاونه وګورم، او چې زما ژوند په بې‌عزتۍ کښې ختم شى؟', 'زۀ د مور د خېتې نه ولې دنیا ته راغلم؟ د دې دپاره پېدا شوم چې په دنیا کشې تکلیفونه او کراونه وګورم، او چې زما ژوند په بې‌عزتی کشې ختم شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_20_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33457, 'Psalms 17:1', 'Psalms', 17, 1, 'واوره زارۍ زما څښتنه، د انصاف دپاره هم د مرستې په خاطر زما فریاد واوره واوره دعا ته زما د بې ریا زړه', 'واوره زاری زما چشتنه، د انصاف دپاره هم د مرستې په خاطر زما فریاد واوره واوره دعا ته زما د بې ریا زره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_17_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33458, 'Psalms 17:2', 'Psalms', 17, 2, 'زما په حق کې ته انصاف وکړه ځکه پوهېږې حقیقت باندې ته', 'زما په حق کې ته انصاف وکره جکه پوهېزې حقیقت باندې ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_17_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33459, 'Psalms 17:3', 'Psalms', 17, 3, 'تا امتحان کړ زما زړه ته په شپه کې راغلې ماته زه دې ښه وازمایلم هېڅ بدي دې پیدا نه کړله په ما کې', 'تا امتحان کر زما زره ته په شپه کې راغلې ماته زه دې شه وازمایلم هېچ بدی دې پیدا نه کرله په ما کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_17_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33460, 'Psalms 17:4', 'Psalms', 17, 4, 'لکه د نورو په شان نه کوم خبرې بدې ما دی کړی اطاعت د ستا د امر ما د ظلم لاره نه ده خپله کړې', 'لکه د نورو په شان نه کوم خبرې بدې ما دی کری اطاعت د ستا د امر ما د ظلم لاره نه ده خپله کرې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_17_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837);